def unique_tuple(values):
    seen = set()
    for v in values:
        if v not in seen:
            seen.add(v)
            values += (v,)
    return values

print(unique_tuple((1, 2, 1, 3)))

def process(data):
    tmp = list(data)
    for i in range(len(tmp)):
        if tmp[i] % 2 == 0:
            tmp[i] *= 2
    return tuple(tmp)

