def safe_update_record(record, updates):
    mapping = {'name': 0, 'age': 1, 'grade': 2}
    new_items = list(record)
    for key, value in updates.items():
        if key in mapping:
            idx = mapping[key]
            new_items[idx] = value
    return tuple(new_items)

# Test
original = ('Alice', 20, 'A')
changes = {'age': 21, 'grade': 'B'}
new_record = safe_update_record(original, changes)
print(original, new_record)

def unique_sorted_from_tuple(data):
    return sorted(set(data))

# Test
source = (5, 3, 5, 2, 3, 9)
print(unique_sorted_from_tuple(source))

